// C implementation of vstodo cmdTag header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_tag.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_tag.go.\n\n#ifndef VSTODO_C_CMD_TAG_H\n#define VSTODO_C_CMD_TAG_H\n\n// Create, list, or delete annotated tags.\n// Equivalent to Go cmdTag function.\n// app — vstodo application context pointer\n// args — command arguments (create <tag> -m \"message\", list, delete <tag>)\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_tag(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_TAG_H